window.POETRY_REGISTER("v5-strict-10-6-0-2469267f0ecb.js",{"poems":[[3434,2],[9851,2],[47353,2],[52521,2],[52804,2],[53263,2],[54490,2],[56616,2],[57623,2],[57946,2],[72842,7],[75308,7],[77952,7],[104613,7],[121854,7],[134259,7],[142073,7],[156473,7],[178369,7],[178781,7],[185587,7],[187767,7],[187920,7],[191123,7],[221362,7],[221365,7],[233420,7],[233440,7],[238404,7],[259566,7],[261523,7],[272196,7],[281976,7],[283043,7],[284190,7],[287469,7],[293223,7],[293616,7],[317943,7],[332787,9],[332970,9],[335917,9],[335918,9],[335920,9],[335925,9],[345333,9],[345993,9],[365420,9],[424562,8],[448202,8],[509931,8],[517395,8],[538831,8],[540524,8],[553278,8],[553578,8],[554284,8],[584933,8],[584934,8],[585525,8],[595847,8],[613263,8],[637840,15],[663352,5],[689628,5],[717582,5]],"pairs":[["中见愁猨吊影而危处兮","呌秋木而长吟",0],["中见愁猨吊影而危处兮","呌秋木而长吟",1],["如此即全胜啄太仓之谷","而更穿人之屋",2],["工每椎拓三面而遗竦诗","以是流传者寡",3],["应麟以元载苏涣为盛唐","震亨改为中唐",4],["又本诗前已收李白名下","惟此多末二句",5],["近有人于江上遇之得此","云即李太白也",6],["首本川本辛本均为足本","但均有所残缺",7],["首先有曾从汉梁王之句","决非子美作也",8],["三第十首作者司户萨照","司户应为官名",9],["待得南楼三弄彻君试看","比从前更瘦生",10],["道自有蓝桥美质诚堪表","倩纤纤捧芳醥",11],["为传语无言分付甘桃李","不比闲花浪草",12],["舍我于此使形影之外兮","唯莽苍之山林",13],["妖鳞怪鬛曾莫识其名兮","怒谺牙以相瞩",14],["盖庶几不淫不移不屈者","而以乐吾之天",15],["吾乃今知贵不若贱无忧","富不若贫无求",16],["呜呼虽九原之不可作兮","庶斯人以发硎",17],["或曰如竹庵之为宗师也","不可赞不可骂",18],["公不见古人有待良不多","利名溺人甚风",19],["于其中间荷负杨歧重担","倒跨三脚驴儿",20],["吾愿托夷齐以为绍介兮","修请谒于黄虞",21],["缅前路之险阻其若此兮","道云远而莫前",22],["岂不见睦州为人太亲切","拶得云门脚折",23],["众皆赏其襮而遗其里兮","知全者不在予",24],["夫何夔魖獝狂之予妬兮","肆为伯明之谗",25],["阊阖重重有栗阶而进兮","不崇朝而折翼",26],["江河之波倒流而西倾兮","溯崇丘而以上",27],["于越守东藩而奉其祀兮","盛侵淫于中世",27],["栖会稽而几不免其身兮","惟种蠡之与谋",27],["争似西湖寺里一队古佛","参退归堂吃茶",28],["卷覆大千舌于洋屿云门","不与摩竭同条",29],["袖掷大千手于梅州衡阳","不与浄名同梦",29],["我欲执鞭追壶中之日月","荐海上之蟠桃",30],["夫何孤鸾一朝而舞镜兮","悼亡赋而鬓霜",31],["宜其谈笑兴起东庵正脉","廓清末流之辙",32],["吾将揭北斗而量九州兮","均人命之所与",33],["登群玉之府兮白云熊熊","祀司天兮毛采",34],["然越人爱公如慈父母兮","愿托歌而永传",35],["若到瑞岩定是打教棒折","而今什么时节",36],["此其所以为柏庭之克家","云公汉章者也",37],["莫不皆是乘虚接响底汉","倚草附木精灵",38],["只等待行满功成朝玉帝","方表男儿有志",39],["斗起慈悲常常似斗无争","斗早得携云朵",40],["普救姻缘西洛客说姻缘","普救寺寻方便",41],["西厢寄寓娇滴滴小红娘","恶狠狠唐三藏",42],["母亲呵怕女孩儿春心荡","百般巧计关防",42],["随分好事梵王宫月轮高","枯木堂香烟罩",43],["开书染病寄简帖又无成","相思病今番甚",44],["安得挽招摇以酌元气兮","妙太极而函三",45],["而畴顾当郑卫之声哇兮","乃独唱乎咸濩",46],["窃独悲夫此花之不幸兮","猗流落乎人间",47],["伫见勒绩燕然收功铜柱","纪万年之青史",48],["吾将挈日月以观乎无始","与夫子兮游遨",49],["古有嘉禾异蓂灵物之属","此其古之遗迹",50],["惴惴焉如贞女之在室兮","佩兰荪而孤芳",51],["风尘灏洞兮不可以久游","返予驾兮初服",52],["或告余以列缺之闪铄兮","屏翳忽而来蔽",53],["惜吾不及无心之落花兮","依湛湛之露枫",54],["余永念夫溟海之怒立兮","愧蓐收之难禁",55],["君不见海师河伯递沉浮","灵不到蓬莱洲",56],["忽流眄夫碧梧之茏葱兮","翳翠竹之萧森",57],["胡为乎煽烈火于馀烬兮","加矰缴于伤羽",58],["夫何玄冥雨雪之愆期兮","羌有失于天职",59],["揽涕泪而感旷荡兮无涯","夜耿耿兮不寐",60],["风尘灏洞兮不可以久游","返予驾兮初服",61],["君不肯入渊手撷骊龙珠","又不肯入庙啼",62],["君不见杯羹且望分强敌","拥彗迎门何踧",63],["最念绰板尊前偷声鬲指","那知醉里残照",64],["这节序恼人间没个君苗","拌掷笔砚全焚",65]]});
